int maxSteps = 100000;
vec2 centre = vec2(0.30, 0.463);

vec2 stepM(vec2 current, vec2 c)
{
    float re = current.x*current.x-current.y*current.y;
    float im = 2.*current.x*current.y;
    return vec2(re, im) + c;
}

int countSteps(vec2 start)
{
    vec2 x = start;
    vec2 c = start;
    for(int i=0;i<maxSteps;++i)
    {
        if (dot(x, x) > 4.)
        {
            return i;
        }
        x = stepM(x, c);
    }
    return maxSteps;
}

vec3 getColor(int id)
{
    int modId = id % 6;
    float red = 0.4 + 0.1 * float(modId);  // Red varies slightly for depth
    float blue = 0.6 + 0.1 * float(modId); // Blue varies slightly for richness
    float lightness = 0.3 + 0.1 * float(modId); // Overall brightness variation

    return vec3(red, 0.0, blue) * lightness; // Modulate lightness for contrast
}

