// Buffer A: Game of Life Logic & State
// Set iChannel0 to "Buffer A" in Shadertoy

// Simple pseudo-random number generator
float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
}

// Function to get the state of a cell (0 for dead, 1 for alive)
// texCoord is the pixel coordinate of the cell to check
float getCellState(vec2 texCoord) {
    // Wrap around for toroidal grid
    vec2 uv = mod(texCoord, iResolution.xy) / iResolution.xy;
    return texture(iChannel0, uv).r;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;

    // Initialization: On the first few frames, or if reset, fill with random values
    // You can also detect a mouse click to reset/re-randomize if iMouse.z > 0.0
    if (iFrame < 5 || (iMouse.z > 0.0 && length(iMouse.xy - fragCoord) < 50.0) ) { // Reset on click near mouse
        // In Buffer A
        float initialState = step(0.5, random(fragCoord.xy + iTime)); // More dense
        //float initialState = step(0.7, random(fragCoord.xy + iTime)); // Adjust threshold for density
        fragColor = vec4(initialState, 0.0, 0.0, 1.0);
        return;
    }

    // Get current cell's state (0 or 1)
    float currentState = getCellState(fragCoord);

    // Count live neighbors
    int liveNeighbors = 0;
    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            if (x == 0 && y == 0) {
                continue; // Don't count self
            }
            // Check neighbor state
            liveNeighbors += int(getCellState(fragCoord + vec2(x, y)));
        }
    }

    float newState = currentState; // Assume state doesn't change initially

    // Apply Conway's Game of Life rules:
    if (currentState > 0.5) { // Cell is alive
        if (liveNeighbors < 2 || liveNeighbors > 3) {
            newState = 0.0; // Dies (underpopulation or overpopulation)
        }
        // else it stays alive (2 or 3 neighbors)
    } else { // Cell is dead
        if (liveNeighbors == 3) {
            newState = 1.0; // Becomes alive (reproduction)
        }
    }

    // Output the new state (store in red channel)
    fragColor = vec4(newState, 0.0, 0.0, 1.0);
}

// Image Shader: Renders the Game of Life state from Buffer A
// Set iChannel0 to "Buffer A" in Shadertoy

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;

    // Read the cell state from Buffer A (stored in the red channel)
    float cellState = texture(iChannel0, uv).r;

    // Render: white for alive, black for dead
    fragColor = vec4(vec3(cellState), 1.0);
}

vec3 hsv2rgb(vec3 c) 
{
    vec3 p = abs(fract(c.x + vec3(0.0, 2.0/3.0, 1.0/3.0)) * 6.0 - 3.0);
    return c.z * mix(vec3(1.0), clamp(p - 1.0, 0.0, 1.0), c.y);
}


float gauss( float x, float mid, float spread, float peak )
{
    float z = x - mid;
    return peak * exp(-z*z/(spread*spread));
}


float hashwithoutsine11(float p)
{
    p = fract(p * .1031);
    p *= p + 33.33;
    p *= p + p;
    return fract(p);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{   
    float wobble;
    wobble += floor(gauss(fragCoord.y, 0.45*iResolution.y, 0.25*iResolution.y, 0.225*iResolution.x*sin(iTime)));
    wobble += floor(gauss(fragCoord.y, 0.55*iResolution.y, 0.25*iResolution.y, 0.125*iResolution.x*cos(iTime*2.315)));
    float m = hashwithoutsine11(fragCoord.x + float(iFrame) + wobble);
    vec3 c = vec3(m-.75, 0.1, m);
    fragColor = vec4(hsv2rgb(c), 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;

    // Sample the pattern from Buffer A
    vec4 bufferAOutput = texture(iChannel0, uv);

    // Calculate the radial distance from the center
    vec2 center = vec2(0.5, 0.5);
    float dist = length(uv - center);

    // Create a vignette effect
    float vignette = smoothstep(0.6, 1.0, 1.0 - dist);

    // Adjust vignette strength
    float strength = 0.4; // Lower values make it less strong
    float blend = mix(1.3, vignette, strength);

    // Apply vignette as a subtle blend
    vec3 color = bufferAOutput.rgb * blend;

    fragColor = vec4(color, 1.0);
}

// Inverse method: distance-based probability dust

// Random function
float hash(vec2 p)
{
    p = fract(p * 0.3183099 + vec2(0.71,0.113));
    p *= 17.0;
    return fract(p.x * p.y * (p.x + p.y));
}


void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord.xy / iResolution.xy;

    // Centered coords (-1 to 1)
    vec2 centered = uv * 2.0 - 1.0;
    centered.x *= iResolution.x / iResolution.y; // correct aspect ratio

    // Distance from center
    float d = length(centered);

    // Calculate a probability falloff
    float prob = smoothstep(0.9, 0.0, d); 
    // (d=0 → prob≈1.0, d>0.6 → prob≈0.0)

    // Generate a random number per pixel

    vec2 seed = fragCoord;
    float noise = hash(seed);
    noise += fract(iTime);
    noise = fract(noise);

    // Compare noise to probability
    float dust = step(noise, prob);

    // Final color
    fragColor = vec4(vec3(dust), 1.0);
}

